(function () {
'use strict';
var storage = {
get: function (key) { try { return window.localStorage.getItem(key); } catch (e) { return null; } },
set: function (key, value) { try { window.localStorage.setItem(key, value); } catch (e) {  } }
};
var $ = function (selector, root) { return (root || document).querySelector(selector); };
var $$ = function (selector, root) { return Array.prototype.slice.call((root || document).querySelectorAll(selector)); };
var mobile = window.matchMedia('(max-width: 900px)');
function toast(message, tone) {
var region = $('[data-erp-toasts]');
if (!region) return;
var item = document.createElement('div');
item.className = 'erp-toast' + (tone ? ' erp-toast--' + tone : '');
var text = document.createElement('span');
text.textContent = message;
var close = document.createElement('button');
close.type = 'button';
close.setAttribute('aria-label', 'Fechar aviso');
close.textContent = '×';
close.addEventListener('click', function () { item.remove(); });
item.appendChild(text);
item.appendChild(close);
region.appendChild(item);
window.setTimeout(function () { item.remove(); }, 6000);
}
window.ErpUI = { toast: toast };
var shell = $('[data-erp-shell]');
if (shell) {
var collapse = $('[data-erp-collapse]');
var openButton = $('[data-erp-nav-open]');
var setCollapsed = function (value) {
shell.classList.toggle('is-collapsed', value);
if (collapse) {
collapse.setAttribute('aria-expanded', String(!value));
collapse.setAttribute('aria-label', value ? 'Expandir menu' : 'Recolher menu');
}
storage.set('erp.sidebar.collapsed', value ? '1' : '0');
};
if (storage.get('erp.sidebar.collapsed') === '1' && !mobile.matches) setCollapsed(true);
if (collapse) collapse.addEventListener('click', function () { setCollapsed(!shell.classList.contains('is-collapsed')); });
var sidebar = $('#erp-sidebar');
var setOpen = function (value) {
shell.classList.toggle('is-nav-open', value);
if (openButton) openButton.setAttribute('aria-expanded', String(value));
if (sidebar) {
if (value) { sidebar.removeAttribute('inert'); var first = $('a, button', sidebar); if (first) first.focus(); }
else if (mobile.matches) { sidebar.setAttribute('inert', ''); }
}
if (!value && openButton && mobile.matches) openButton.focus();
};
var syncBreakpoint = function () {
shell.classList.remove('is-nav-open');
if (!sidebar) return;
if (mobile.matches) { sidebar.setAttribute('inert', ''); shell.classList.remove('is-collapsed'); }
else { sidebar.removeAttribute('inert'); if (storage.get('erp.sidebar.collapsed') === '1') shell.classList.add('is-collapsed'); }
};
syncBreakpoint();
if (mobile.addEventListener) mobile.addEventListener('change', syncBreakpoint);
if (openButton) openButton.addEventListener('click', function () { setOpen(true); });
$$('[data-erp-nav-close]').forEach(function (el) { el.addEventListener('click', function () { setOpen(false); }); });
document.addEventListener('keydown', function (event) {
if (event.key === 'Escape' && shell.classList.contains('is-nav-open')) setOpen(false);
});
$$('.erp-nav__group > summary').forEach(function (summary) {
summary.addEventListener('click', function () { if (shell.classList.contains('is-collapsed')) setCollapsed(false); });
});
var groups = $$('.erp-nav__group');
groups.forEach(function (group) {
group.addEventListener('toggle', function () {
if (!group.open) return;
groups.forEach(function (other) { if (other !== group && other.open) other.open = false; });
});
});
}
var dropdowns = $$('[data-erp-dropdown]');
document.addEventListener('click', function (event) {
dropdowns.forEach(function (d) { if (d.open && !d.contains(event.target)) d.open = false; });
});
document.addEventListener('keydown', function (event) {
if (event.key !== 'Escape') return;
dropdowns.forEach(function (d) { if (d.open) { d.open = false; var s = $('summary', d); if (s) s.focus(); } });
});
var navSearch = $('[data-erp-navsearch]');
var navToggle = navSearch && $('[data-erp-navsearch-toggle]', navSearch);
var navPanel = navSearch && $('.erp-navsearch__panel', navSearch);
var setNavSearch = function (open) {
if (!navPanel) return;
navPanel.hidden = !open;
navToggle.setAttribute('aria-expanded', String(open));
if (open) { var input = $('[data-erp-search]', navPanel); if (input) input.focus(); }
};
if (navToggle) {
navToggle.addEventListener('click', function () { setNavSearch(navPanel.hidden); });
document.addEventListener('click', function (event) { if (!navSearch.contains(event.target)) setNavSearch(false); });
document.addEventListener('keydown', function (event) {
if (event.key === 'Escape' && !navPanel.hidden) { setNavSearch(false); navToggle.focus(); }
});
}
$$('[data-erp-condo-switch]').forEach(function (form) {
var select = $('select', form);
if (select) select.addEventListener('change', function () { form.submit(); });
});
var searchInput = $('[data-erp-search]');
var searchResults = $('#erp-search-results');
var indexNode = $('#erp-search-index');
if (searchInput && searchResults && indexNode) {
var index = [];
try { index = JSON.parse(indexNode.textContent || '[]'); } catch (e) { index = []; }
var normalize = function (text) { return String(text).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); };
var focused = -1;
var render = function () {
var term = normalize(searchInput.value.trim());
searchResults.innerHTML = '';
focused = -1;
if (term.length < 2) { searchResults.hidden = true; searchInput.setAttribute('aria-expanded', 'false'); return; }
var hits = index.filter(function (item) { return normalize(item.n + ' ' + item.g).indexOf(term) !== -1; }).slice(0, 12);
if (!hits.length) {
var empty = document.createElement('p');
empty.className = 'erp-field__hint';
empty.style.padding = '8px 10px';
empty.textContent = 'Nenhuma página encontrada.';
searchResults.appendChild(empty);
}
hits.forEach(function (item) {
var link = document.createElement('a');
link.href = item.u;
link.setAttribute('role', 'option');
link.textContent = item.n;
var group = document.createElement('small');
group.textContent = item.g;
link.appendChild(group);
searchResults.appendChild(link);
});
searchResults.hidden = false;
searchInput.setAttribute('aria-expanded', 'true');
};
searchInput.addEventListener('input', render);
searchInput.addEventListener('keydown', function (event) {
var links = $$('a', searchResults);
if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
event.preventDefault();
if (!links.length) return;
focused = (focused + (event.key === 'ArrowDown' ? 1 : -1) + links.length) % links.length;
links.forEach(function (l, i) { l.classList.toggle('is-focused', i === focused); });
} else if (event.key === 'Enter' && links[focused > -1 ? focused : 0]) {
event.preventDefault();
window.location.href = links[focused > -1 ? focused : 0].href;
} else if (event.key === 'Escape') {
searchInput.value = ''; render();
}
});
document.addEventListener('click', function (event) { if (!searchInput.parentNode.contains(event.target)) { searchResults.hidden = true; searchInput.setAttribute('aria-expanded', 'false'); } });
document.addEventListener('keydown', function (event) {
if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); if (navToggle) setNavSearch(true); else searchInput.focus(); }
});
}
$$('[data-erp-modal-open]').forEach(function (trigger) {
trigger.addEventListener('click', function () {
var dialog = document.getElementById(trigger.getAttribute('data-erp-modal-open'));
if (dialog && typeof dialog.showModal === 'function') { dialog.showModal(); dialog._erpTrigger = trigger; }
});
});
$$('dialog.erp-modal').forEach(function (dialog) {
dialog.addEventListener('click', function (event) { if (event.target === dialog) dialog.close(); });
dialog.addEventListener('close', function () { if (dialog._erpTrigger) dialog._erpTrigger.focus(); });
$$('[data-erp-modal-close]', dialog).forEach(function (b) { b.addEventListener('click', function () { dialog.close(); }); });
});
$$('[role="tablist"]').forEach(function (list) {
var tabs = $$('[role="tab"]', list);
var select = function (tab) {
tabs.forEach(function (t) {
var on = t === tab;
t.setAttribute('aria-selected', String(on));
t.tabIndex = on ? 0 : -1;
var panel = document.getElementById(t.getAttribute('aria-controls'));
if (panel) panel.hidden = !on;
});
};
tabs.forEach(function (tab, i) {
tab.addEventListener('click', function () { select(tab); });
tab.addEventListener('keydown', function (event) {
if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
var next = tabs[(i + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length];
select(next); next.focus();
});
});
});
$$('[data-erp-table]').forEach(function (wrap) {
var table = $('table', wrap);
var body = table && table.tBodies[0];
if (!body) return;
var rows = Array.prototype.slice.call(body.rows);
var perPage = parseInt(wrap.getAttribute('data-per-page') || '8', 10);
var page = 1;
var pager = wrap.parentNode.querySelector('[data-erp-pager]');
var draw = function () {
var pages = Math.max(1, Math.ceil(rows.length / perPage));
page = Math.min(page, pages);
rows.forEach(function (row, i) { row.hidden = i < (page - 1) * perPage || i >= page * perPage; body.appendChild(row); });
if (!pager) return;
var info = $('[data-erp-pager-info]', pager);
if (info) info.textContent = rows.length ? 'Mostrando ' + ((page - 1) * perPage + 1) + '–' + Math.min(page * perPage, rows.length) + ' de ' + rows.length : 'Nenhum registro';
var holder = $('[data-erp-pager-pages]', pager);
if (!holder) return;
holder.innerHTML = '';
var add = function (label, target, disabled, current, aria) {
var b = document.createElement('button');
b.type = 'button'; b.textContent = label; b.disabled = disabled;
if (aria) b.setAttribute('aria-label', aria);
if (current) b.setAttribute('aria-current', 'page');
b.addEventListener('click', function () { page = target; draw(); });
holder.appendChild(b);
};
add('‹', page - 1, page === 1, false, 'Página anterior');
for (var p = 1; p <= pages; p++) add(String(p), p, false, p === page, 'Página ' + p);
add('›', page + 1, page === pages, false, 'Próxima página');
};
$$('[data-erp-sort]', table).forEach(function (button, column) {
var index = parseInt(button.getAttribute('data-erp-sort'), 10);
button.addEventListener('click', function () {
var dir = button.getAttribute('data-dir') === 'asc' ? 'desc' : 'asc';
$$('[data-erp-sort]', table).forEach(function (b) { b.removeAttribute('data-dir'); b.closest('th').removeAttribute('aria-sort'); });
button.setAttribute('data-dir', dir);
button.closest('th').setAttribute('aria-sort', dir === 'asc' ? 'ascending' : 'descending');
rows.sort(function (a, b) {
var x = a.cells[index].getAttribute('data-sort') || a.cells[index].textContent.trim();
var y = b.cells[index].getAttribute('data-sort') || b.cells[index].textContent.trim();
var nx = parseFloat(x), ny = parseFloat(y);
var cmp = !isNaN(nx) && !isNaN(ny) ? nx - ny : x.localeCompare(y, 'pt-BR');
return dir === 'asc' ? cmp : -cmp;
});
page = 1; draw();
});
});
var scope = wrap.closest('[data-erp-list]') || wrap.parentNode;
var textFilter = scope.querySelector('[data-erp-table-filter]');
var selectFilters = $$('[data-erp-select-filter]', scope);
if (textFilter || selectFilters.length) {
var all = rows.slice();
var apply = function () {
var term = textFilter ? textFilter.value.trim().toLowerCase() : '';
var picks = selectFilters.map(function (s) { return s.value; }).filter(Boolean);
all.forEach(function (row) { row.hidden = true; });
rows = all.filter(function (row) {
if (term && row.textContent.toLowerCase().indexOf(term) === -1) return false;
var cells = Array.prototype.map.call(row.cells, function (c) { return c.textContent.trim(); });
return picks.every(function (p) { return cells.indexOf(p) !== -1; });
});
page = 1; draw();
};
if (textFilter) textFilter.addEventListener('input', apply);
selectFilters.forEach(function (s) { s.addEventListener('change', apply); });
var reset = scope.querySelector('[data-erp-filter-reset]');
if (reset) reset.addEventListener('click', function () { window.setTimeout(apply, 0); });
}
draw();
});
$$('form[data-erp-validate]').forEach(function (form) {
form.setAttribute('novalidate', '');
form.addEventListener('submit', function (event) {
var firstInvalid = null;
$$('input, select, textarea', form).forEach(function (field) {
var holder = field.closest('.erp-field');
var error = holder && $('.erp-field__error', holder);
var ok = field.checkValidity();
field.setAttribute('aria-invalid', String(!ok));
if (error) { error.textContent = ok ? '' : (field.validationMessage || 'Campo inválido.'); }
if (!ok && !firstInvalid) firstInvalid = field;
});
if (firstInvalid) { event.preventDefault(); firstInvalid.focus(); toast('Revise os campos destacados.', 'warning'); return; }
if (form.hasAttribute('data-erp-pending')) { event.preventDefault(); toast(form.getAttribute('data-erp-pending'), 'warning'); }
});
});
$$('[data-erp-summary]').forEach(function (summary) {
var form = document.getElementById(summary.getAttribute('data-erp-summary'));
if (!form) return;
var sync = function () {
$$('[data-erp-summary-for]', summary).forEach(function (dd) {
var field = document.getElementById(dd.getAttribute('data-erp-summary-for'));
var value = field ? (field.type === 'checkbox' ? (field.checked ? 'Sim' : 'Não') : field.value) : '';
dd.textContent = value || '—';
});
};
form.addEventListener('input', sync);
form.addEventListener('change', sync);
form.addEventListener('reset', function () { window.setTimeout(sync, 0); });
});
document.addEventListener('click', function (event) {
var trigger = event.target.closest('button[data-erp-pending], a[data-erp-pending]');
if (!trigger || trigger.closest('form[data-erp-validate]') && trigger.type === 'submit') return;
event.preventDefault();
toast(trigger.getAttribute('data-erp-pending') || 'Operação pendente: o backend deste módulo ainda não foi implementado.', 'warning');
});
$$('form[data-erp-confirm]').forEach(function (form) {
form.addEventListener('submit', function (event) {
if (!form.checkValidity()) return;
if (!window.confirm(form.getAttribute('data-erp-confirm'))) { event.preventDefault(); return; }
var button = $('[type="submit"]', form);
if (button) { button.classList.add('is-loading'); button.setAttribute('aria-busy', 'true'); window.setTimeout(function () { button.disabled = true; }, 0); }
});
});
$$('[data-erp-invoices]').forEach(function (root) {
var api = root.getAttribute('data-api');
var canManage = root.getAttribute('data-can-manage') === '1';
var csrf = function () { return (($('[name="csrf"]', root) || {}).value || ''); };
var esc = function (text) { var d = document.createElement('div'); d.textContent = text == null ? '' : String(text); return d.innerHTML; };
var brl = function (cents) { return 'R$ ' + (cents / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); };
var call = function (method, url, body) {
var options = { method: method, credentials: 'same-origin', headers: { 'Accept': 'application/json', 'X-CSRF-Token': csrf() } };
if (body !== undefined) { options.headers['Content-Type'] = 'application/json'; options.body = JSON.stringify(body); }
return fetch(url, options).then(function (response) {
return response.json().catch(function () { return {}; }).then(function (json) {
if (!response.ok) { var error = new Error((json.error && json.error.message) || 'Não foi possível concluir. Tente de novo.'); error.fields = json.error && json.error.fields; throw error; }
return json;
});
}, function () { throw new Error('Não foi possível falar com o servidor. Tente de novo.'); });
};
var busy = function (button, on) { if (!button) return; button.disabled = on; button.classList.toggle('is-loading', on); if (on) button.setAttribute('aria-busy', 'true'); else button.removeAttribute('aria-busy'); };
var reload = function () { window.setTimeout(function () { window.location.reload(); }, 700); };
var itemsDialog = $('#invoice-items', root);
var itemsBody = itemsDialog && $('[data-invoice-items]', itemsDialog);
var renderItems = function (invoice) {
var editable = canManage && invoice.status === 'draft';
var rows = (invoice.items || []).map(function (item) {
var state = item.entry_id ? (item.paid_on ? 'Paga' : 'A receber') : (invoice.status === 'issued' ? '—' : 'Ainda não emitida');
var amount = editable
? '<form class="erp-invoice-item" data-item="' + item.id + '"><label class="erp-sr-only" for="inv-item-' + item.id + '">Valor da unidade ' + esc(item.unit_label) + '</label>' +
'<input class="erp-input erp-input--sm" id="inv-item-' + item.id + '" name="amount" inputmode="decimal" value="' + esc((item.amount_cents / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2 })) + '" required>' +
'<button type="submit" class="erp-btn erp-btn--sm">Salvar</button></form>'
: brl(item.amount_cents);
return '<tr><td><strong>' + esc(item.unit_label) + '</strong></td><td class="is-num">' + amount + '</td><td>' + esc(state) + '</td></tr>';
}).join('');
itemsBody.innerHTML =
'<p><strong>' + esc(invoice.type_name) + '</strong> · ' + esc(invoice.condominium_name) + ' · ' + esc(invoice.competence.slice(5) + '/' + invoice.competence.slice(0, 4)) +
' · ' + esc(invoice.status_label) + ' · total <strong data-invoice-total>' + brl(invoice.amount_cents) + '</strong></p>' +
(editable ? '<p class="erp-muted">Ajuste o valor de uma unidade e salve. O total da fatura é recalculado.</p>' : '') +
'<div class="erp-table-wrap"><table class="erp-table"><thead><tr><th>Unidade</th><th class="is-num">Valor</th><th>Conta a receber</th></tr></thead><tbody>' +
(rows || '<tr><td colspan="3">Nenhuma unidade ativa na fatura.</td></tr>') + '</tbody></table></div>';
$$('form[data-item]', itemsBody).forEach(function (form) {
form.addEventListener('submit', function (event) {
event.preventDefault();
var button = $('[type="submit"]', form);
busy(button, true);
call('PATCH', api + '/' + invoice.id + '/items/' + form.getAttribute('data-item'), { amount_cents: $('[name="amount"]', form).value.trim() })
.then(function (json) { busy(button, false); toast('Valor da unidade atualizado.', 'success'); renderItems(json.data); itemsDialog._changed = true; })
.catch(function (error) { busy(button, false); toast(error.message, 'danger'); });
});
});
};
if (itemsDialog) itemsDialog.addEventListener('close', function () { if (itemsDialog._changed) { itemsDialog._changed = false; window.location.reload(); } });
$$('[data-invoice-open]', root).forEach(function (button) {
button.addEventListener('click', function () {
if (!itemsDialog) return;
itemsBody.innerHTML = '<p class="erp-muted">Carregando…</p>';
if (typeof itemsDialog.showModal === 'function') itemsDialog.showModal();
call('GET', api + '/' + button.getAttribute('data-invoice-open'))
.then(function (json) { renderItems(json.data); })
.catch(function (error) { itemsBody.innerHTML = '<div class="erp-alert erp-alert--danger" role="alert">' + esc(error.message) + '</div>'; });
});
});
$$('[data-invoice-issue]', root).forEach(function (button) {
button.addEventListener('click', function () {
if (!window.confirm('Emitir a fatura ' + button.getAttribute('data-label') + '? Cada unidade passa a ter uma conta a receber e os valores não podem mais ser ajustados.')) return;
busy(button, true);
call('POST', api + '/' + button.getAttribute('data-invoice-issue') + '/issue', {})
.then(function () { toast('Fatura emitida. As contas a receber das unidades foram geradas.', 'success'); reload(); })
.catch(function (error) { busy(button, false); toast(error.message, 'danger'); });
});
});
var cancelDialog = $('#invoice-cancel', root);
var cancelForm = cancelDialog && $('[data-invoice-cancel-form]', cancelDialog);
$$('[data-invoice-cancel]', root).forEach(function (button) {
button.addEventListener('click', function () {
if (!cancelDialog) return;
cancelForm.reset();
cancelForm.setAttribute('data-id', button.getAttribute('data-invoice-cancel'));
$('[data-invoice-cancel-label]', cancelDialog).textContent = 'Fatura ' + button.getAttribute('data-label') + '.';
if (typeof cancelDialog.showModal === 'function') cancelDialog.showModal();
});
});
if (cancelForm) cancelForm.addEventListener('submit', function (event) {
event.preventDefault();
var reason = $('[name="reason"]', cancelForm).value.replace(/\s+/g, ' ').trim();
if (reason.length < 5) { toast('Explique o motivo do cancelamento (pelo menos 5 caracteres).', 'warning'); return; }
var button = $('[type="submit"]', cancelForm);
busy(button, true);
call('POST', api + '/' + cancelForm.getAttribute('data-id') + '/cancel', { reason: reason })
.then(function () { cancelDialog.close(); toast('Fatura cancelada.', 'success'); reload(); })
.catch(function (error) { busy(button, false); toast(error.message, 'danger'); });
});
var prepareForm = $('[data-invoice-prepare-form]', root);
if (prepareForm) {
var condo = $('[name="condominium_id"]', prepareForm);
var types = $('[data-invoice-types]', prepareForm);
var method = $('[name="method"]', prepareForm);
var amountLabel = $('[data-invoice-amount-label]', prepareForm);
var loadTypes = function () {
var id = parseInt(condo.value || '0', 10);
types.innerHTML = '<option value="">' + (id ? 'Carregando…' : 'Escolha o condomínio') + '</option>';
if (!id) return;
call('GET', root.getAttribute('data-types-api') + '?status=active&condominium_id=' + id)
.then(function (json) {
var list = json.data || [];
types.innerHTML = '<option value="">' + (list.length ? 'Escolha' : 'Nenhum tipo de fatura ativo') + '</option>' + list.map(function (type) {
var amount = parseInt(type.default_amount_cents || '0', 10);
return '<option value="' + type.id + '">' + esc(type.name) + (amount > 0 ? ' (' + brl(amount) + ')' : '') + '</option>';
}).join('');
})
.catch(function (error) { types.innerHTML = '<option value="">Tipos indisponíveis</option>'; toast(error.message, 'danger'); });
};
condo.addEventListener('change', loadTypes);
$$('[data-erp-modal-open="invoice-prepare"]').forEach(function (b) { b.addEventListener('click', function () { if (types.options.length <= 1) loadTypes(); }); });
method.addEventListener('change', function () { amountLabel.textContent = method.value === 'fraction' ? 'Valor total a ratear (R$)' : 'Valor por unidade (R$)'; });
prepareForm.addEventListener('submit', function (event) {
event.preventDefault();
if (!prepareForm.reportValidity()) return;
var body = {};
['condominium_id', 'invoice_type_id', 'competence', 'due_on', 'method', 'amount_cents', 'notes'].forEach(function (name) { var field = $('[name="' + name + '"]', prepareForm); if (field && field.value.trim() !== '') body[name] = field.value.trim(); });
var button = $('[type="submit"]', prepareForm);
busy(button, true);
call('POST', api, body)
.then(function (json) { toast('Fatura preparada com ' + ((json.data && json.data.units_count) || 0) + ' unidade(s). Confira os valores e emita.', 'success'); reload(); })
.catch(function (error) { busy(button, false); toast(error.message, 'danger'); });
});
}
});
$$('form[data-erp-generate-recurring]').forEach(function (form) {
form.addEventListener('submit', function (event) {
event.preventDefault();
var button = $('[type="submit"]', form);
var competence = (($('[name="competence"]', form) || {}).value || '').trim();
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(competence)) { toast('Escolha o mês da competência.', 'warning'); return; }
var label = competence.slice(5) + '/' + competence.slice(0, 4);
if (!window.confirm('Gerar os lançamentos de ' + label + ' a partir dos lançamentos fixos ativos? Os que já foram gerados não se repetem.')) return;
var body = { competence: competence };
var condominium = parseInt(form.getAttribute('data-condominium') || '0', 10);
if (condominium > 0) body.condominium_id = condominium;
var busy = function (on) { if (!button) return; button.disabled = on; button.classList.toggle('is-loading', on); if (on) button.setAttribute('aria-busy', 'true'); else button.removeAttribute('aria-busy'); };
busy(true);
fetch(form.getAttribute('data-erp-generate-recurring'), {
method: 'POST', credentials: 'same-origin',
headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-Token': (($('[name="csrf"]', form) || {}).value || '') },
body: JSON.stringify(body)
}).then(function (response) {
return response.json().catch(function () { return {}; }).then(function (json) { return { ok: response.ok, json: json }; });
}).then(function (res) {
busy(false);
if (!res.ok) { toast((res.json.error && res.json.error.message) || 'Não foi possível gerar os lançamentos.', 'danger'); return; }
var data = res.json.data || {};
var created = (data.created || []).length, skipped = (data.skipped || []).length, failed = Object.keys(data.failed || {}).length;
var parts = [created === 1 ? '1 lançamento gerado' : created + ' lançamentos gerados'];
if (skipped) parts.push(skipped === 1 ? '1 já existia' : skipped + ' já existiam');
if (failed) parts.push(failed === 1 ? '1 com erro (revise o lançamento fixo)' : failed + ' com erro (revise os lançamentos fixos)');
toast(label + ': ' + parts.join(', ') + '.', failed ? 'warning' : 'success');
}).catch(function () { busy(false); toast('Não foi possível falar com o servidor. Tente de novo.', 'danger'); });
});
});
$$('form[data-erp-loading]').forEach(function (form) {
form.addEventListener('submit', function () { var b = $('[type="submit"]', form); if (b) { b.classList.add('is-loading'); b.setAttribute('aria-busy', 'true'); } });
});
})();
(function () {
'use strict';
function fmt(n) { return Math.round(n).toLocaleString('pt-BR'); }
function distance(lat1, lng1, lat2, lng2) {
var r = 6371008.8, rad = Math.PI / 180;
var dPhi = (lat2 - lat1) * rad, dLambda = (lng2 - lng1) * rad;
var a = Math.sin(dPhi / 2) * Math.sin(dPhi / 2) + Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(dLambda / 2) * Math.sin(dLambda / 2);
return 2 * r * Math.asin(Math.min(1, Math.sqrt(a)));
}
function locate(onOk, onError) {
if (!('geolocation' in navigator)) { onError('Este aparelho ou navegador não informa a localização.'); return; }
if (!window.isSecureContext) { onError('A localização só funciona com o ERP aberto em HTTPS.'); return; }
navigator.geolocation.getCurrentPosition(onOk, function (err) {
onError(err && err.code === 1 ? 'Permissão de localização negada. Libere a localização para o ERP nas configurações do navegador.' : 'Não foi possível obter a localização. Vá para um local aberto e tente de novo.');
}, { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 });
}
var checkin = document.querySelector('[data-insp-checkin]');
if (checkin) {
var box = checkin.querySelector('[data-insp-gps]');
var status = box.querySelector('[data-insp-gps-status]');
var detail = box.querySelector('[data-insp-gps-detail]');
var condo = checkin.querySelector('[name="condominium_id"]');
var refs = JSON.parse(checkin.getAttribute('data-insp-references') || '{}');
var note = checkin.querySelector('[data-insp-note]');
var last = null;
var evaluate = function () {
if (!last) { return; }
var ref = refs[condo.value];
var c = last.coords;
checkin.querySelector('[name="latitude"]').value = c.latitude.toFixed(7);
checkin.querySelector('[name="longitude"]').value = c.longitude.toFixed(7);
checkin.querySelector('[name="accuracy"]').value = Math.round(c.accuracy);
if (!ref) {
box.setAttribute('data-state', 'inside');
status.textContent = 'Localização obtida';
detail.textContent = 'Precisão de ±' + fmt(c.accuracy) + ' m. Este condomínio ainda não tem ponto cadastrado; a posição será registrada no relatório.';
note.hidden = true;
return;
}
var d = distance(c.latitude, c.longitude, ref.latitude, ref.longitude);
var inside = d <= ref.radius_m + Math.min(ref.radius_m, c.accuracy);
box.setAttribute('data-state', inside ? 'inside' : 'outside');
status.textContent = inside ? 'Você está no condomínio' : 'Você está a ' + fmt(d) + ' m do condomínio';
detail.textContent = 'Precisão de ±' + fmt(c.accuracy) + ' m. Raio aceito: ' + fmt(ref.radius_m) + ' m.';
note.hidden = inside;
};
var run = function () {
box.setAttribute('data-state', 'loading');
status.textContent = 'Obtendo sua localização…';
detail.textContent = 'Permita o acesso à localização quando o navegador perguntar.';
locate(function (pos) { last = pos; evaluate(); }, function (msg) {
box.setAttribute('data-state', 'error');
status.textContent = 'Sem localização';
detail.textContent = msg + ' Para seguir, explique o motivo abaixo.';
note.hidden = false;
});
};
checkin.querySelector('[data-insp-locate]').addEventListener('click', run);
condo.addEventListener('change', evaluate);
run();
}
document.querySelectorAll('[data-insp-item-form]').forEach(function (form) {
var input = form.querySelector('input[type="file"]');
if (!input) { return; }
input.addEventListener('change', function () {
if (!input.files || !input.files.length) { return; }
if (input.files[0].size > 15 * 1024 * 1024) {
alert('A foto passa de 15 MB. Tire outra com resolução menor.');
input.value = '';
return;
}
locate(function (pos) {
form.querySelector('[name="latitude"]').value = pos.coords.latitude.toFixed(7);
form.querySelector('[name="longitude"]').value = pos.coords.longitude.toFixed(7);
}, function () {});
});
});
var here = document.querySelector('[data-insp-use-here]');
if (here) {
here.addEventListener('click', function () {
var form = here.closest('form');
here.disabled = true;
locate(function (pos) {
form.querySelector('[name="latitude"]').value = pos.coords.latitude.toFixed(7);
form.querySelector('[name="longitude"]').value = pos.coords.longitude.toFixed(7);
here.disabled = false;
}, function (msg) { alert(msg); here.disabled = false; });
});
}
})();